STDL_HELP = [
    "# stdlib_ext — 12980 عنصراً عربياً",
]

_STDL_TOKEN = re.compile(
    r"(?P<dot>\.)?"
    r"(?P<word>(?!\d)[\w\u064B-\u065F\u0670]+)"
    r"(?P<open>\s*\()?"
)

USER_NAMES = set()


def _stdl_replace(match):
    dot = match.group("dot")
    word = match.group("word")
    open_paren = match.group("open")
    if word in USER_NAMES:
        return match.group(0)
    if dot:
        if open_paren and word in STDL_METHODS:
            return "." + STDL_METHODS[word] + open_paren
        if word in STDL_PROPS:
            return "." + STDL_PROPS[word]
        return match.group(0)
    if word in STDL_CONSTS:
        return STDL_CONSTS[word]
    if word in STDL_FUNCS:
        return STDL_FUNCS[word] + (open_paren or "")
    return match.group(0)


def STDL_SUBSTITUTE(text):
    """يترجم كلمات المكتبة في نص واحد ويُرجع المترجم."""
    if not text:
        return text
    return _STDL_TOKEN.sub(_stdl_replace, text)
